import os
from datetime import datetime, timedelta
from google.cloud import monitoring_v3

client = monitoring_v3.MetricServiceClient()
project_name = f"projects/{os.environ['GOOGLE_CLOUD_PROJECT']}"

def compare_metrics(resource_type_1, resource_id_1, resource_type_2, resource_id_2, metric_type, window_minutes=10):
    end_time = datetime.utcnow()
    start_time = end_time - timedelta(minutes=window_minutes)
    interval = monitoring_v3.TimeInterval({
        "end_time": {"seconds": int(end_time.timestamp())},
        "start_time": {"seconds": int(start_time.timestamp())}
    })

    def fetch_metric(resource_type, resource_id):
        filter_str = f'resource.type="{resource_type}" AND resource.labels.instance_id="{resource_id}" AND metric.type="{metric_type}"'
        results = client.list_time_series(
            request={
                "name": project_name,
                "filter": filter_str,
                "interval": interval,
                "view": monitoring_v3.ListTimeSeriesRequest.TimeSeriesView.FULL
            }
        )
        points = []
        for ts in results:
            for point in ts.points:
                points.append(point.value.double_value)
        return points

    points_1 = fetch_metric(resource_type_1, resource_id_1)
    points_2 = fetch_metric(resource_type_2, resource_id_2)

    avg_1 = sum(points_1) / len(points_1) if points_1 else 0
    avg_2 = sum(points_2) / len(points_2) if points_2 else 0

    return {
        "resource_1_avg": avg_1,
        "resource_2_avg": avg_2,
        "difference": avg_1 - avg_2,
        "window_minutes": window_minutes
    }
